'use strict';
// Technical alpha export, registered doorway compositing and uniform resize.
// Artwork is generated by ImageGen; this does not redraw architecture.
const fs=require('fs'),path=require('path'),crypto=require('crypto'),sharp=require('sharp');
const root=path.resolve(__dirname,'../../../..');
const out=path.join(root,'game/art/buildings/warehouse/v2');
const qa=path.join(root,'docs/art/qa/warehouse-v2');
const W=1254, H=1254, size=800, ratio=size/W, rawScale=0.095;
const key=[244,5,248], keyDominance=239, cutoff=200;
const threshold=[670,1190];
const door=[[457,704],[878,611],[878,1039],[463,1128]];
const life=JSON.parse(fs.readFileSync(path.join(__dirname,'life-measurements.json'),'utf8'));
const windows=life.windows, panes=life.window_panes;
const hash=b=>crypto.createHash('sha256').update(b).digest('hex');
const point=p=>p.map(v=>v*ratio);
function bounds(b,w,h,t=25){let l=w,u=h,r=-1,d=-1,n=0;for(let y=0;y<h;y++)for(let x=0;x<w;x++)if(b[(y*w+x)*4+3]>t){l=Math.min(l,x);u=Math.min(u,y);r=Math.max(r,x);d=Math.max(d,y);n++;}return {bbox:[l,u,r-l+1,d-u+1],pixels:n};}
function inside(x,y,p){let yes=false;for(let i=0,j=p.length-1;i<p.length;j=i++){const a=p[i],b=p[j];if((a[1]>y)!=(b[1]>y)&&x<(b[0]-a[0])*(y-a[1])/(b[1]-a[1])+a[0])yes=!yes;}return yes;}
async function raw(file){const r=await sharp(file).removeAlpha().raw().toBuffer({resolveWithObject:true});if(r.info.width!==W||r.info.height!==H)throw Error('Changed source size; remeasure registration');return r.data;}
function alphaExport(rgb){const rgba=Buffer.alloc(W*H*4);for(let i=0,j=0;i<rgb.length;i+=3,j+=4){const d=Math.min(rgb[i],rgb[i+2])-rgb[i+1];const a=d>=cutoff?0:Math.max(0,Math.min(1,1-d/keyDominance));rgba[j+3]=Math.round(a*255);if(a<=0)continue;for(let c=0;c<3;c++)rgba[j+c]=Math.round(Math.max(0,Math.min(255,(rgb[i+c]-(1-a)*key[c])/a)));}return rgba;}
// Remove disconnected residual key pixels; the warehouse is one connected object.
// This preserves the measured silhouette and partial-alpha architecture edges.
const alphaCleanup=[];
function keepObject(rgba){
 const seen=new Uint8Array(W*H),queue=new Int32Array(W*H);let largest=[],components=0,removed=0;
 for(let seed=0;seed<W*H;seed++){
  if(seen[seed]||!rgba[seed*4+3])continue;let read=0,write=0;queue[write++]=seed;seen[seed]=1;
  while(read<write){const at=queue[read++],x=at%W;for(const next of [x>0?at-1:-1,x<W-1?at+1:-1,at>=W?at-W:-1,at<W*(H-1)?at+W:-1]){if(next<0||seen[next]||!rgba[next*4+3])continue;seen[next]=1;queue[write++]=next;}}
  components++;if(write>largest.length)largest=Array.from(queue.subarray(0,write));
 }
 const keep=new Uint8Array(W*H);for(const at of largest)keep[at]=1;
 for(let at=0;at<W*H;at++)if(!keep[at]&&rgba[at*4+3]){rgba.fill(0,at*4,at*4+4);removed++;}
 alphaCleanup.push({connected_components:components,retained_pixels:largest.length,disconnected_key_pixels_removed:removed});return rgba;
}
async function saveVariant(name,pixels){const master=path.join(__dirname,name+'-rgba-master.png');await sharp(pixels,{raw:{width:W,height:H,channels:4}}).png().toFile(master);const file=path.join(out,name+'.png');await sharp(pixels,{raw:{width:W,height:H,channels:4}}).resize(size,size,{kernel:'lanczos3'}).png().toFile(file);const rgba=await sharp(file).ensureAlpha().raw().toBuffer();return {file,sha256:hash(fs.readFileSync(file)),rgba_sha256:hash(rgba),alpha:bounds(rgba,size,size),rgba};}
(async()=>{
fs.mkdirSync(out,{recursive:true});fs.mkdirSync(qa,{recursive:true});
const closedSource=path.join(__dirname,'closed-key-master.png');
const closed=keepObject(alphaExport(await raw(closedSource)));
const finished=await saveVariant('finished',closed);
const daySource=path.join(__dirname,'day-open-key-master.png');
if(!fs.existsSync(daySource)){console.log(JSON.stringify({closed_only:true,alpha:finished.alpha}));return;}
const generatedOpen=keepObject(alphaExport(await raw(daySource))),day=Buffer.from(closed);
let replaced=0;for(let y=0;y<H;y++)for(let x=0;x<W;x++){if(!inside(x+0.5,y+0.5,door))continue;const i=(y*W+x)*4;generatedOpen.copy(day,i,i,i+4);replaced++;}
const opened=await saveVariant('day-open',day);
const manifest={schema_version:1,building_id:'warehouse',asset_version:'v2',canvas:[size,size],finished_image:'finished.png',finished_sha256:finished.sha256,finished_rgba_sha256:finished.rgba_sha256,alpha_bbox:finished.alpha.bbox,day_open_image:'day-open.png',day_open_sha256:opened.sha256,day_open_rgba_sha256:opened.rgba_sha256,day_open_alpha_bbox:opened.alpha.bbox,door_threshold:point(threshold),sort_foot:point(threshold),label_anchor:point([650,18]),source_to_world:rawScale/ratio,life:{windows:windows.map(q=>q.map(point)),window_panes:panes.map(win=>win.map(q=>q.map(point))),chimney:point(life.chimney)}};
fs.writeFileSync(path.join(out,'manifest.json'),JSON.stringify(manifest,null,2)+'\n');
let outsideChanged=0;for(let y=0;y<H;y++)for(let x=0;x<W;x++){if(inside(x+0.5,y+0.5,door))continue;const i=(y*W+x)*4;for(let c=0;c<4;c++)if(day[i+c]!==closed[i+c])outsideChanged++;}
fs.writeFileSync(path.join(qa,'production-export.json'),JSON.stringify({date:'2026-09-13',source_canvas:[W,H],production_canvas:[size,size],raw_to_world:rawScale,uniform_source_to_production:ratio,threshold_source:threshold,door_patch_source:door,source_key:{measured_modal_rgb:key,dominance:keyDominance,cutoff,method:'a=clamp(1-(min(r,b)-g)/239); pure-background dominance>=200 removed; unmatte against measured source key'},closed_source_sha256:hash(fs.readFileSync(closedSource)),open_source_sha256:hash(fs.readFileSync(daySource)),alpha_cleanup:alphaCleanup,closed_alpha:finished.alpha,day_open_alpha:opened.alpha,doorway_pixels_replaced:replaced,outside_door_changed_bytes:outsideChanged,manifest,limitation:'Pixel export is not runtime or raised-ground QA; manual anchors require native review.'},null,2)+'\n');
console.log(JSON.stringify({manifest,doorway_pixels_replaced:replaced,outside_door_changed_bytes:outsideChanged}));
})();
